#include "projectile/motion_detector.hpp"
#include <opencv2/imgproc.hpp>
namespace projectile { MotionDetector::MotionDetector(const Config& c):config_(c){mog_=cv::createBackgroundSubtractorMOG2(c.mog_history,c.mog_var_threshold,c.mog_shadows);} MotionMasks MotionDetector::process(const cv::Mat& b,const cv::Mat& g){MotionMasks m;if(config_.tophat){auto k=cv::getStructuringElement(cv::MORPH_ELLIPSE,{config_.tophat_kernel,config_.tophat_kernel});cv::Mat w,bl;cv::morphologyEx(g,w,cv::MORPH_TOPHAT,k);cv::morphologyEx(g,bl,cv::MORPH_BLACKHAT,k);if(config_.tophat_mode=="white")m.tophat=w;else if(config_.tophat_mode=="black")m.tophat=bl;else cv::max(w,bl,m.tophat);cv::threshold(m.tophat,m.tophat,config_.tophat_threshold,255,cv::THRESH_BINARY);}if(config_.frame_diff){frames_.push_back(g.clone());while(frames_.size()>size_t(2*config_.frame_diff_gap+1))frames_.pop_front();if(frames_.size()==size_t(2*config_.frame_diff_gap+1)){cv::Mat a,d;cv::absdiff(frames_.back(),frames_[frames_.size()-1-config_.frame_diff_gap],a);cv::absdiff(frames_[frames_.size()-1-config_.frame_diff_gap],frames_.front(),d);cv::threshold(a,a,config_.frame_diff_threshold,255,cv::THRESH_BINARY);cv::threshold(d,d,config_.frame_diff_threshold,255,cv::THRESH_BINARY);cv::bitwise_and(a,d,m.frame_diff);}}if(config_.bg_sub){mog_->apply(b,m.background);++bg_frames_;cv::threshold(m.background,m.background,200,255,cv::THRESH_BINARY);m.warmed_up=bg_frames_>=config_.mog_history;}cv::Mat t=cv::Mat::zeros(g.size(),CV_8U);if(!m.frame_diff.empty())cv::bitwise_or(t,m.frame_diff,t);if(!m.background.empty())cv::bitwise_or(t,m.background,t);if(!m.tophat.empty())cv::bitwise_and(m.tophat,t,m.combined);else m.combined=t;if(config_.morph_clean&&!m.combined.empty()){auto k=cv::getStructuringElement(cv::MORPH_RECT,{config_.morph_kernel,config_.morph_kernel});cv::morphologyEx(m.combined,m.cleaned,cv::MORPH_OPEN,k);cv::morphologyEx(m.cleaned,m.cleaned,cv::MORPH_CLOSE,k);}else m.cleaned=m.combined;return m;}}
